import React, { useEffect, useState } from 'react';
import { db } from '../firebase-config';
import { collection, query, where, getDocs } from 'firebase/firestore';
import { auth } from '../firebase-config';
import { PieChart, Pie, Cell, Tooltip } from 'recharts'; // Import des composants pour le diagramme
import ProgressChart from '../components/ProgressChart'; // Import du composant ProgressChart
import './Profile.css'; // Import des styles pour les cartes

const Profile = () => {
  const [activities, setActivities] = useState([]);
  const [totalRemainingSadaqa, setTotalRemainingSadaqa] = useState(0);
  const [investmentGoal, setInvestmentGoal] = useState(0); // Objectif d'investissement
  const [currentProgress, setCurrentProgress] = useState(0); // Progression actuelle

  useEffect(() => {
    const fetchActivities = async () => {
      try {
        const user = auth.currentUser;
        if (user) {
          const activitiesCollectionRef = collection(db, 'activities');
          const q = query(activitiesCollectionRef, where('userId', '==', user.uid));
          const querySnapshot = await getDocs(q);

          const fetchedActivities = [];
          let sadaqaRemaining = 0;
          let totalGains = 0;

          querySnapshot.forEach((doc) => {
            const data = doc.data();
            fetchedActivities.push({ id: doc.id, ...data });

            // Calculer le montant restant pour les Sadaqa
            if (data.sadaqaStatus === 'Pas encore' || data.sadaqaStatus === 'Partiellement payé') {
              const remaining = data.sadaqaAmount - (data.sadaqaPaid || 0);
              sadaqaRemaining += remaining;
            }

            // Calculer les gains totaux pour la progression
            totalGains += data.totalGains || 0;
          });

          setActivities(fetchedActivities);
          setTotalRemainingSadaqa(sadaqaRemaining);

          // Calculer l'objectif d'investissement comme la somme des investissements
          const totalInvestment = fetchedActivities.reduce((acc, activity) => acc + (activity.investment || 0), 0);

          // Définir l'objectif d'investissement et la progression actuelle
          setInvestmentGoal(totalInvestment);
          setCurrentProgress(totalGains);
        }
      } catch (error) {
        console.error('Erreur lors du chargement des activités :', error);
      }
    };

    fetchActivities();
  }, []);

  // Fonction pour obtenir le nom complet du jour
  const getFullDate = (dateString) => {
    const date = new Date(dateString);
    const options = { weekday: 'long', year: 'numeric', month: 'numeric', day: 'numeric' };
    return date.toLocaleDateString('fr-FR', options);
  };

  return (
    <div className="container mt-5">
      <h1 className="text-center mb-4">👤 Profil</h1>

      {/* Afficher les activités par jour */}
      <div className="activities-container">
        {activities.map((activity, index) => {
          const data = [
            { name: 'Investissement', value: activity.investment || 0 },
            { name: 'Gains', value: activity.totalGains || 0 },
            { name: 'Sadaqa', value: activity.sadaqaAmount || 0 },
          ];
          const COLORS = ['#6a1b9a', '#283593', '#d32f2f']; // Couleurs pour le diagramme

          return (
            <div
              key={activity.id}
              className={`activity-card activity-card-${index % 4}`} // Couleurs différentes pour chaque carte
            >
              <h5 className="activity-date">{getFullDate(activity.date)}</h5>
              <div className="chart-container">
                <PieChart width={200} height={200}>
                  <Pie
                    data={data}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    outerRadius={80}
                    fill="#8884d8"
                    label
                  >
                    {data.map((entry, i) => (
                      <Cell key={`cell-${i}`} fill={COLORS[i % COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip />
                </PieChart>
              </div>
              <p>💵 <strong>Investissement :</strong> {activity.investment} Dhs</p>
              <p>📈 <strong>Gains totaux :</strong> {activity.totalGains} Dhs</p>
              <p>🤲 <strong>Sadaqa :</strong> {activity.sadaqaAmount} Dhs</p>
              <p>🔖 <strong>Statut de la Sadaqa :</strong> {activity.sadaqaStatus}</p>
            </div>
          );
        })}
      </div>

      {/* Afficher le montant total restant pour les Sadaqa */}
      <div className="card mt-4">
        <div className="card-body">
          <h3 className="card-title">🤲 Sadaqa restante</h3>
          <p>Montant total restant : <strong>{totalRemainingSadaqa.toFixed(2)} Dhs</strong></p>
        </div>
      </div>

      {/* Barre de progression pour atteindre l'investissement */}
      <div className="card mt-4">
        <div className="card-body">
          <h3 className="card-title">📈 Progression vers l'objectif d'investissement</h3>
          {investmentGoal > 0 ? (
            <>
              <ProgressChart gains={currentProgress} investment={investmentGoal} />
              <p className="mt-3">
                Vous avez atteint <strong>{currentProgress.toFixed(2)} Dhs</strong> sur un objectif de <strong>{investmentGoal.toFixed(2)} Dhs</strong>.
              </p>
            </>
          ) : (
            <p className="text-danger">Aucun objectif d'investissement défini.</p>
          )}
        </div>
      </div>
    </div>
  );
};

export default Profile;
